using System;using System.Collections.Generic;using System.IO;using System.Linq;using System.Text.RegularExpressions;using System.Xml;
namespace ServiceTool{
internal static class ServiceHostingConfig{
internal static List<string> Read(string executable){var result=new List<string>();string root=Path.GetDirectoryName(executable);foreach(string file in new[]{executable+".config",Path.Combine(root,"Config.xml"),Path.Combine(root,"appsettings.json"),Path.Combine(root,"appsettings.Production.json"),Path.Combine(root,"configs","appsettings.json"),Path.Combine(root,"configs","appsettings.Production.json")}){if(!File.Exists(file)||new FileInfo(file).Length>1024*1024)continue;try{if(file.EndsWith(".json",StringComparison.OrdinalIgnoreCase)){string text=File.ReadAllText(file);foreach(Match match in Regex.Matches(text,"\"Urls\"\\s*:\\s*\"([^\"]+)\"",RegexOptions.IgnoreCase))foreach(string value in match.Groups[1].Value.Split(';'))Add(result,value);}else{var doc=new XmlDocument{XmlResolver=null};using(var reader=XmlReader.Create(file,new XmlReaderSettings{DtdProcessing=DtdProcessing.Prohibit,XmlResolver=null}))doc.Load(reader);foreach(XmlNode node in doc.SelectNodes("//*")){if(node.Attributes!=null){var key=node.Attributes["key"];var value=node.Attributes["value"];if(key!=null&&value!=null&&Regex.IsMatch(key.Value,"^(HttpHostPort|WebApiPort|WebApiBaseAddress|ServiceBaseAddress|ApiURL|HostUrl)$",RegexOptions.IgnoreCase))Add(result,value.Value);var address=node.Attributes["baseAddress"];if(address!=null)Add(result,address.Value);}if(node.ChildNodes.Count==1&&Regex.IsMatch(node.LocalName,"^(Port|HttpHostPort|WebApiPort|ServiceBaseAddress|ApiURL)$",RegexOptions.IgnoreCase))Add(result,node.InnerText);}}}catch(XmlException){}catch(IOException){}catch(UnauthorizedAccessException){}}return result.Distinct().ToList();}
static void Add(List<string> list,string value){int port;if(Int32.TryParse(value,out port)&&port>0&&port<=65535)value="http://localhost:"+port+"/";value=value.Replace("0.0.0.0","localhost").Replace("[::]","localhost").Replace("http://*:","http://localhost:").Replace("http://+:","http://localhost:");Uri uri;if(Uri.TryCreate(value,UriKind.Absolute,out uri)&&uri.IsLoopback&&(uri.Scheme=="http"||uri.Scheme=="https")&&String.IsNullOrEmpty(uri.UserInfo))list.Add(uri.AbsoluteUri);}
}}
